  "MOD_APPLY_WALL_FINISH_SPRAY_BACKROLL_COMBINED": {
    "module_id": "MOD_APPLY_WALL_FINISH_SPRAY_BACKROLL_COMBINED",
    "name": "Apply Wall Finish (Spray + Backroll, Combined Wall+Ceiling Pass)",
    "phase": "apply",
    "intent": "Wall finish variant for the combined wall+ceiling finish pass (same product/sheen/color on both substrates). Identical task list to MOD_APPLY_WALL_SPRAY_BACKROLL. Rate overrides on task_ref entries go here when painter data justifies the combined-flow speedup.",
    "tasks": [
      {
        "task_ref": "TSK_SPRAY_WALL_FINISH"
      },
      {
        "task_ref": "TSK_BACKROLL_WALL_FINISH"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": true,
      "complexity": true
    },
    "doctrine": "Combined-pass finish variant. Paired with MOD_APPLY_CEIL_FINISH_SPRAY_BACKROLL_COMBINED inside SCN_COMBINED_WALLS_CEILING_FINISH_* scenarios. Rates currently match non-combined; add rate_override on task_ref entries when painter data confirms the combined-flow speedup."
  },
  "MOD_APPLY_WALL_PRIME_ROLL": {
    "module_id": "MOD_APPLY_WALL_PRIME_ROLL",
    "name": "Apply Wall Primer (Roll Method)",
    "phase": "apply",
    "intent": "Cut in to ceiling line freehand with brush, then roll primer onto bare drywall walls with an 18-inch roller. Single coat of primer regardless of QT — primer never gets a second coat in NC residential. Texture variants (orange peel, knockdown) require slower laydown to fill the profile.",
    "tasks": [
      {
        "task_ref": "TSK_WALL_CUT_IN_CEILING_PRIME"
      },
      {
        "task_ref": "TSK_WALL_ROLL_PRIMER"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": true,
      "complexity": true
    },
    "doctrine": "Primer cut-in is slower than finish cut-in because the painter is fighting wet primer that can lap-mark visibly even though it's hidden by finish coats — the prime cut-in line establishes where the finish painter will cut in, so straightness matters at QT4. Roll primer baseline (350 SF/hr) is the smooth rate; FAC_TEXTURE handles the textured slowdown — tune there if the textured:smooth ratio needs adjusting. QT4 slowdown comes from FAC_QT separately, so no special collapse logic needed here."
  },
  "MOD_APPLY_WALL_PRIME_SPRAY_BACKROLL": {
    "module_id": "MOD_APPLY_WALL_PRIME_SPRAY_BACKROLL",
    "name": "Apply Wall Primer (Spray + Backroll)",
    "phase": "apply",
    "intent": "Spray PVA primer onto bare drywall and immediately backroll the wet film. NC production standard for prime. Spray pass is fast, backroll works the primer into mud joints and texture. Single coat regardless of QT. No ceiling cutin needed because spray pattern handles the ceiling line cleanly.",
    "tasks": [
      {
        "task_ref": "TSK_WALL_SPRAY_PRIMER"
      },
      {
        "task_ref": "TSK_WALL_BACKROLL_PRIMER"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": true,
      "complexity": true
    },
    "doctrine": "Spray primer (600 SF/hr baseline) is meaningfully faster than spray finish because primer is thicker and lays down with fewer passes. Backroll (400 SF/hr baseline) handles filling into texture and joint absorption. FAC_TEXTURE eligibility is author-set via the Modifier Editor UI — set per-task if one task (e.g. spray) should opt out while another (e.g. backroll) stays on. QT4 spray slowdown comes from FAC_QT. No ceiling cutin task — spray handles the ceiling edge cleanly, the finish painter establishes the visible cut line later."
  },
  "MOD_APPLY_WALL_PRIME_SPRAY_BACKROLL_COMBINED": {
    "module_id": "MOD_APPLY_WALL_PRIME_SPRAY_BACKROLL_COMBINED",
    "name": "Apply Wall Primer (Spray + Backroll, Combined Wall+Ceiling Pass)",
    "phase": "apply",
    "intent": "Wall prime variant for the pre-trim NC workflow where walls and ceiling are primed in one continuous spray pass. Identical task list to MOD_APPLY_WALL_PRIME_SPRAY_BACKROLL. Rates are expected to be tuned up slightly once painter data confirms the combined-pace speedup (continuous flow, less pausing between substrates). For Phase 1A the baseline rates match non-combined; tune via the Modifier UI.",
    "tasks": [
      {
        "task_ref": "TSK_WALL_SPRAY_PRIMER"
      },
      {
        "task_ref": "TSK_WALL_BACKROLL_PRIMER"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": true,
      "complexity": true
    },
    "doctrine": "Combined-pass variant of MOD_APPLY_WALL_PRIME_SPRAY_BACKROLL. Scenarios that match ctx.prime_mode === 'combined' use this module instead of the standard version. Task list is identical — the savings in combined mode come from (a) shared scenario-level setup/teardown dedup, (b) per-task cleanup gating (floor teardown tasks fire only in separate mode), and (c) optional rate overrides on these task_refs once painter data justifies them. For Phase 1A, rates are unchanged from non-combined. Next step: author rate_per_hour overrides here after verifying combined-pace speedup on a job."
  },
  "MOD_APPLY_WALL_PRIME_SPRAY_ONLY": {
    "module_id": "MOD_APPLY_WALL_PRIME_SPRAY_ONLY",
    "name": "Apply Wall Primer (Spray, No Backroll)",
    "phase": "apply",
    "intent": "Spray PVA primer onto bare drywall, no backroll. Used when builder-grade schedule demands speed over mud-joint compaction — common on production NC. Single coat regardless of QT.",
    "tasks": [
      {
        "task_id": "TSK_WALL_SPRAY_PRIMER",
        "name": "Spray Wall Primer (No Backroll)",
        "ps_key": "PS_SURFACE_SF.WALL_FIELD",
        "uom": "SF",
        "skill_level": "experienced",
        "rate_per_hour": 900
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Spray-only primer is ~50% faster than spray+backroll because the backroll pass is skipped. Tradeoff: mud joints may flash through without the backroll working primer into the profile — acceptable on builder-grade NC where finish coats will hide any uneven absorption."
  },
