  "MOD_DOOR_GLASS_MASK": {
    "module_id": "MOD_DOOR_GLASS_MASK",
    "name": "Mask Door Glass Panes (French Doors)",
    "phase": "setup",
    "intent": "Tape off each glass pane in french doors before painting. Only fires for door_type=french. Quantity is per pane, not per door — a 15-lite french door has 15 panes per side, or 30 panes per door. Both setup (tape) and teardown (untape) tasks bundled because the unmask is fast and conceptually paired with the mask.",
    "tasks": [
      {
        "task_ref": "TSK_DOOR_GLASS_MASK",
        "applies_when": {
          "door_type": [
            "french"
          ]
        }
      },
      {
        "task_ref": "TSK_DOOR_GLASS_UNMASK",
        "applies_when": {
          "door_type": [
            "french"
          ]
        }
      }
    ],
    "modifier_eligibility": {
      "qt": false,
      "height": false,
      "texture": false,
      "complexity": false
    },
    "doctrine": "10 panes/hr setup = 6 minutes per pane to tape edges and apply paper if needed. Unmask is 2x faster (20 panes/hr) — pulling tape is fast. Only fires for french door types; the door_type gate at task level handles the conditional automatically. Module is technically tagged setup phase but contains both setup and teardown tasks; this matches the source spec's bundling and Phase 1c can split if needed."
  },
  "MOD_DOOR_PRIME": {
    "module_id": "MOD_DOOR_PRIME",
    "name": "Prime Door (Bare Wood Only)",
    "phase": "prime",
    "intent": "Apply primer coat to bare wood doors only. Skipped entirely for factory-primed doors. One brush task and one spray task; whichever fires depends on application_method.",
    "tasks": [
      {
        "task_ref": "TSK_DOOR_PRIME_SPRAY",
        "applies_when": {
          "application_method": [
            "spray"
          ],
          "substrate": [
            "bare_wood"
          ]
        }
      },
      {
        "task_ref": "TSK_DOOR_PRIME_BRUSH",
        "applies_when": {
          "application_method": [
            "brush"
          ],
          "substrate": [
            "bare_wood"
          ]
        }
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": false,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Spray prime (12 sides/hr) is 2.4x faster than brush prime (5 sides/hr). Both gate by substrate=bare_wood — factory-primed doors skip this entire module via task-level applies_when. The whole module is technically always 'in' the scenario but its tasks SKIP when conditions don't match. This is the same gating pattern that drove the trim state-branching demo, applied to door priming."
  },
  "MOD_EXT_CAULK": {
    "module_id": "MOD_EXT_CAULK",
    "name": "Exterior Caulking — Joint Prep, Application, Inspection",
    "phase": "apply",
    "intent": "Complete caulking workflow: ground protect, mask adjacent, stage materials, joint clean, backer rod (when needed), sealant application, inspect, adhesion check, tape remove.",
    "tasks": [
      {
        "task_ref": "TSK_CAULK_PROTECT_GROUND"
      },
      {
        "task_ref": "TSK_CAULK_MASK_ADJACENT"
      },
      {
        "task_ref": "TSK_CAULK_STAGE_MATERIALS"
      },
      {
        "task_ref": "TSK_CAULK_JOINT_CLEAN"
      },
      {
        "task_ref": "TSK_CAULK_BACKER_ROD",
        "applies_when": {
          "joint_complexity": [
            "backer_rod"
          ]
        }
      },
      {
        "task_ref": "TSK_CAULK_APPLY_SIMPLE",
        "applies_when": {
          "joint_complexity": [
            "simple_bead"
          ]
        }
      },
      {
        "task_ref": "TSK_CAULK_APPLY_BACKER",
        "applies_when": {
          "joint_complexity": [
            "backer_rod"
          ]
        }
      },
      {
        "task_ref": "TSK_CAULK_INSPECT"
      },
      {
        "task_ref": "TSK_CAULK_ADHESION_CHECK"
      },
      {
        "task_ref": "TSK_CAULK_TAPE_REMOVE"
      }
    ],
    "modifier_eligibility": {
      "qt": false,
      "height": false,
      "texture": false,
      "complexity": false,
      "condition": false
    },
    "doctrine": "Standalone caulk spec. LF-based. Caulk IS the deliverable (not a prep step). Must occur AFTER primer, BEFORE finish coats. No QT, no access modifier (shares access with painting spec). 4 sealant types drive material cost, not labor rate. Simple bead 125 LF/hr, backer rod 87 LF/hr. Silicone excluded — never paintable."
  },
  "MOD_GRAIN_FILL": {
    "module_id": "MOD_GRAIN_FILL",
    "name": "Wood Grain Fill (Paint Grade Add-On)",
    "phase": "prime",
    "intent": "Standalone add-on for open-grain hardwoods being painted. Fills grain pores before finish coats. Inserts between parent prime and parent finish specs. QT3=1 fill, QT4=2 fills, QT5=3 fills + final 400 grit.",
    "tasks": [
      {
        "task_ref": "TSK_GRAIN_SAND_PREP"
      },
      {
        "task_ref": "TSK_GRAIN_FILL_COAT"
      },
      {
        "task_ref": "TSK_GRAIN_SAND_BETWEEN"
      },
      {
        "task_ref": "TSK_GRAIN_FINAL_SAND",
        "applies_when": {
          "quality_tier": [
            "QT5"
          ]
        }
      },
      {
        "task_ref": "TSK_GRAIN_PRIME_SEAL"
      },
      {
        "task_ref": "TSK_GRAIN_SAND_PRIME"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": false,
      "complexity": true,
      "condition": false
    },
    "doctrine": "Grain fill add-on for open-grain hardwoods (oak, ash, walnut, mahogany, hickory) being painted. Inserts between parent prime and finish specs. Fill coat at 70 SF/hr (skim application with cross-grain technique). QT3=1 fill, QT4=2 fills, QT5=3 fills + final 400 grit glass-smooth. Surface profile modifier is dominant: flat=1.0, light=1.3, medium=2.0, heavy=2.8. Wood species modifier (deep/moderate grain) on fill and sand tasks. No protection zones — runs within parent spec's workspace."
  },
