  "MOD_PREP_COMBINED_PRIME": {
    "module_id": "MOD_PREP_COMBINED_PRIME",
    "name": "Prep for Combined Wall+Ceiling Prime",
    "phase": "prep",
    "intent": "Single pre-prime prep pass across both walls and ceiling. Replaces per-substrate MOD_PREP_WALL_PRIME + MOD_PREP_CEILING_PRIME when walls and ceiling are primed together — the painter does one dust/vacuum sweep of the room rather than two. Inspect tasks still reference each substrate's pre-prime ps_key so the work is quantified correctly.",
    "tasks": [
      {
        "task_ref": "TSK_WALL_INSPECT_PREPRIME"
      },
      {
        "task_ref": "TSK_CEIL_INSPECT_PREPRIME"
      },
      {
        "task_ref": "TSK_WALL_VACUUM_DUST_PREPRIME"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Two inspects (one per substrate) but only ONE vacuum/dust pass — the painter sweeps the room once, not once per substrate. Rate on the vacuum task already covers the floor-area roll-up at the room level; no double-count. If a project has unusually large ceiling that warrants its own dust pass, add TSK_CEIL_VACUUM_DUST_PREPRIME here as a local override."
  },
  "MOD_PREP_COMBINED_WC_FINISH": {
    "module_id": "MOD_PREP_COMBINED_WC_FINISH",
    "name": "Prep for Combined Wall+Ceiling Finish",
    "phase": "prep",
    "intent": "Inspect + repair primed walls AND ceiling in one prep pass. Two inspects (each target their substrate-specific ps_key for quantity attribution), spackle/sand/spot-prime per substrate, then ONE combined vacuum pass (the painter sweeps the room once, not once per substrate).",
    "tasks": [
      {
        "task_ref": "TSK_INSPECT_PRIMED_WALL"
      },
      {
        "task_ref": "TSK_SPACKLE_WALL_DEFECTS"
      },
      {
        "task_ref": "TSK_SAND_SPACKLE_WALL"
      },
      {
        "task_ref": "TSK_SPOT_PRIME_WALL"
      },
      {
        "task_ref": "TSK_INSPECT_PRIMED_CEILING"
      },
      {
        "task_ref": "TSK_SPACKLE_CEILING_DEFECTS"
      },
      {
        "task_ref": "TSK_SAND_SPACKLE_CEILING"
      },
      {
        "task_ref": "TSK_SPOT_PRIME_CEILING"
      },
      {
        "task_ref": "TSK_VACUUM_REPAIR_DUST_CEILING"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Mirrors the separate-mode prep modules (MOD_PREP_INSPECT_REPAIR + MOD_PREP_INSPECT_REPAIR_CEILING) but drops TSK_DUST_WIPE_WALL in favor of a single ceiling-focused vacuum (TSK_VACUUM_REPAIR_DUST_CEILING) that sweeps the whole room's subfloor. This is the intended dedup — the painter doesn't vacuum twice. Substrate-specific inspect/spackle/sand/spot-prime tasks preserve per-substrate quantification."
  },
