  "MOD_PREP_TRIM_INITIAL": {
    "module_id": "MOD_PREP_TRIM_INITIAL",
    "name": "Trim Initial Prep (Wood)",
    "phase": "prep",
    "intent": "Dust wipe trim, fill fastener holes, fill end grain (MDF and FJP only), caulk joints between trim pieces, light sand smooth. Sets the trim up for primer adhesion. Some tasks gate by substrate condition because they only apply to certain wood types.",
    "tasks": [
      {
        "task_ref": "TSK_TRIM_DUST_WIPE"
      },
      {
        "task_ref": "TSK_TRIM_FILL_FASTENERS"
      },
      {
        "task_ref": "TSK_TRIM_FILL_END_GRAIN",
        "applies_when": {
          "substrate": [
            "bare_mdf",
            "bare_fjp"
          ]
        }
      },
      {
        "task_ref": "TSK_TRIM_CAULK_JOINTS"
      },
      {
        "task_ref": "TSK_TRIM_SAND_PREP"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": false,
      "texture": false,
      "complexity": true
    },
    "doctrine": "End grain fill only fires for MDF and FJP — solid wood and factory-primed don't need it because solid wood has no exposed grain ends and factory-primed already has end grain sealed. Caulking joints applies to all conditions because joints exist in any trim install. Sand prep is light sand to break primer adhesion sites; not the same as full sanding (which is part of inspect/repair on subsequent passes)."
  },
  "MOD_PREP_TRIM_PAINT": {
    "module_id": "MOD_PREP_TRIM_PAINT",
    "name": "Trim Paint Prep (Post-Primer)",
    "phase": "prep",
    "intent": "Inspect cured primer, light sand to break the surface, touch up any caulk gaps or fill misses revealed by primer, clean dust before finish coats. This is the second-pass prep — the first pass happened in trim prime. Most rates are estimated to fill gaps in the source spec.",
    "tasks": [
      {
        "task_ref": "TSK_TRIM_INSPECT_PRIMER"
      },
      {
        "task_ref": "TSK_TRIM_LIGHT_SAND_PRIMER"
      },
      {
        "task_ref": "TSK_TRIM_TOUCHUP_CAULK"
      },
      {
        "task_ref": "TSK_TRIM_TOUCHUP_FILL"
      },
      {
        "task_ref": "TSK_TRIM_CLEAN_DUST_PREP"
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": false,
      "texture": false,
      "complexity": true
    },
    "doctrine": "This prep module reuses the trim prime prep pattern (inspect → repair → clean) but at faster rates because the painter is working on already-primed surfaces with mostly-clean substrate. Source spec is missing rates for inspect/touchup tasks — the rates here are educated estimates flagged with RATE_GAP_FILL in each task. Phase 1c should validate these against field timings."
  },
